/* ═══ PHOTO PLACEHOLDER ═══ */
function PhotoPlaceholder({ hue = 0, aspect = "4/3", label, style = {}, size = "md" }) {
  const sizes = { sm: 13, md: 14, lg: 16 };
  return (
    <div style={{
      aspectRatio: aspect, borderRadius: 12, overflow: "hidden", position: "relative",
      background: `linear-gradient(135deg, #7a1414 0%, #3d0a0a 55%, #120404 100%)`,
      display: "flex", alignItems: "center", justifyContent: "center", flexDirection: "column",
      gap: 8, ...style,
    }}>
      <span style={{ fontSize: 32, opacity: 0.5 }}>📷</span>
      {label && <span style={{ fontFamily: font.body, fontSize: sizes[size], fontWeight: 500, color: "rgba(255,255,255,0.55)", textAlign: "center", padding: "0 12px" }}>{label}</span>}
    </div>
  );
}

/* ═══ CELSIUS SPONSOR STRIP ═══ */
const CELSIUS_LOGO_WHITE = "data:image/png;base64,";
const CELSIUS_LOGO = "data:image/png;base64,";

function CelsiusBanner({ variant = "inline" }) {
  if (variant === "strip") {
    return (
      <div style={{
        background: "#2E2E2E",
        padding: "18px 24px", display: "flex", alignItems: "center", justifyContent: "center", gap: 16,
      }}>
        <span style={{ fontFamily: font.display, fontSize: 15, fontWeight: 700, color: C.white, textTransform: "uppercase", letterSpacing: 1.5 }}>Proudly sponsored by</span>
        <img src={CELSIUS_LOGO_WHITE} alt="Celsius - Live Fit" style={{ height: 34, objectFit: "contain" }} />
      </div>
    );
  }
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
      <span style={{ fontFamily: font.body, fontSize: 11, color: C.textLight, textTransform: "uppercase", letterSpacing: 1 }}>Sponsored by</span>
      <img src={CELSIUS_LOGO} alt="Celsius - Live Fit" style={{ height: 22, objectFit: "contain" }} />
    </div>
  );
}


/* ═══ SHARED UI ═══ */
function Btn({ children, onClick, variant = "primary", style = {} }) {
  const v = {
    primary: { background: C.red, color: C.white, border: "none" },
    outline: { background: "transparent", color: C.red, border: `2px solid ${C.red}` },
    white: { background: C.white, color: C.charcoal, border: "none" },
    gold: { background: C.gold, color: C.white, border: "none" },
    ghost: { background: "transparent", color: C.white, border: `2px solid rgba(255,255,255,.35)` },
  };
  return (
    <button onClick={onClick} style={{
      ...v[variant], padding: "13px 30px", borderRadius: 8,
      fontFamily: font.display, fontSize: 15, fontWeight: 700,
      cursor: "pointer", transition: "all .2s", letterSpacing: 0.3, ...style,
    }}>{children}</button>
  );
}

function SectionWrap({ children, bg = C.white, style = {} }) {
  return <section style={{ padding: "80px clamp(20px, 5vw, 72px)", background: bg, ...style }}>{children}</section>;
}

function SectionHead({ title, sub, light, align = "center" }) {
  return (
    <div style={{ marginBottom: 48, textAlign: align }}>
      <h2 style={{ fontFamily: font.display, fontSize: "clamp(28px, 4vw, 40px)", fontWeight: 800, color: light ? C.white : C.charcoal, margin: 0, letterSpacing: -0.5 }}>{title}</h2>
      {sub && <p style={{ fontFamily: font.body, fontSize: 17, color: light ? "rgba(255,255,255,.65)" : C.textMid, marginTop: 12, maxWidth: 560, lineHeight: 1.6, ...(align === "center" ? { marginLeft: "auto", marginRight: "auto" } : {}) }}>{sub}</p>}
    </div>
  );
}

/* ═══ NAV ═══ */
const PAGES = ["Home", "Team", "Events"];

function Nav({ page, setPage }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <nav style={{
        position: "fixed", top: 0, left: 0, right: 0, zIndex: 100,
        background: "#2E2E2E", display: "flex", alignItems: "center",
        justifyContent: "space-between", padding: "0 clamp(16px, 4vw, 48px)", height: 60,
        boxShadow: "0 2px 16px rgba(0,0,0,.3)",
      }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, cursor: "pointer" }} onClick={() => setPage("Home")}>
          <span style={{ fontFamily: font.display, fontWeight: 700, fontSize: 15, color: C.white, letterSpacing: 0.3 }}>Toastmasters at Miami University</span>
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: 6 }} className="dNav">
          {PAGES.map(p => (
            <button key={p} onClick={() => setPage(p)} style={{
              background: page === p ? "rgba(255,255,255,.1)" : "transparent",
              color: C.white, border: "none", borderRadius: 6, padding: "7px 16px",
              fontFamily: font.display, fontSize: 14, fontWeight: page === p ? 700 : 500,
              cursor: "pointer",
            }}>{p}</button>
          ))}
          <Btn onClick={() => setPage("Join")} variant="primary" style={{ marginLeft: 8, padding: "8px 22px", fontSize: 13 }}>Sign Up</Btn>
        </div>

        <button onClick={() => setOpen(!open)} className="mBtn" style={{ display: "none", background: "none", border: "none", color: C.white, fontSize: 26, cursor: "pointer" }}>☰</button>

        {open && (
          <div style={{ position: "fixed", top: 60, left: 0, right: 0, bottom: 0, background: "#2E2E2E", display: "flex", flexDirection: "column", padding: 24, gap: 6, zIndex: 99 }}>
            {[...PAGES, "Sign Up"].map(p => (
              <button key={p} onClick={() => { setPage(p === "Sign Up" ? "Join" : p); setOpen(false); }} style={{
                background: (p === "Sign Up" ? "Join" : p) === page ? C.red : "transparent",
                color: C.white, border: "none", borderRadius: 8, padding: "14px 20px",
                fontFamily: font.display, fontSize: 18, fontWeight: 600, cursor: "pointer", textAlign: "left",
              }}>{p}</button>
            ))}
          </div>
        )}
      </nav>

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700;800&family=Inter:wght@400;500;600;700&display=swap');
        @media(max-width:768px){.dNav{display:none!important}.mBtn{display:block!important}}
      `}</style>
    </>
  );
}

/* ═══ TEAM CARD ═══ */
function TeamCard({ member, compact = false }) {
  return (
    <div style={{
      background: C.white, borderRadius: 16, overflow: "hidden",
      boxShadow: "0 4px 20px rgba(0,0,0,.07)", border: `1px solid ${C.lightGray}`,
      display: "flex", flexDirection: "column",
    }}>
      {member.photo
        ? <div style={{ width: "100%", aspectRatio: compact ? "4/5" : "4/5", overflow: "hidden" }}>
            <img src={member.photo} alt={member.name} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: member.photoPosition || "center 15%", display: "block", transform: `scale(${member.photoZoom || 1})` }} />
          </div>
        : <PhotoPlaceholder hue={member.photoHue} aspect={compact ? "3/2" : "4/3"} label={compact ? null : "Member photo"} />
      }
      <div style={{ background: "#891824", padding: compact ? "18px 20px" : "24px 26px", flex: 1, display: "flex", flexDirection: "column" }}>
        <div style={{ fontFamily: font.display, fontSize: 12, fontWeight: 700, color: C.white, textTransform: "uppercase", letterSpacing: 1.2, marginBottom: 4 }}>{member.role}</div>
        <h3 style={{ fontFamily: font.display, fontSize: compact ? 18 : 20, fontWeight: 700, margin: "0 0 12px", color: C.white }}>{member.name}</h3>
        {!compact && (
          <>
            <p style={{
              fontFamily: font.body, fontSize: 15, fontStyle: "italic", color: "rgba(255,255,255,.85)",
              lineHeight: 1.5, margin: "0 0 14px", paddingLeft: 14,
              borderLeft: `3px solid ${C.white}`,
            }}>{member.quote}</p>
            <p style={{ fontFamily: font.body, fontSize: 14, color: "rgba(255,255,255,.7)", lineHeight: 1.6, margin: 0, marginTop: "auto" }}>{member.reflection}</p>
          </>
        )}
      </div>
    </div>
  );
}

