/* ═══ EVENTS PAGE ═══════════════════════════ */
/* ═══════════════════════════════════════════ */
function EventsPage({ setPage }) {
  const typeColors = { Meeting: C.red, Recruitment: C.gold, Competition: "#4A4A4A", Social: "#2BAA7E" };

  return (
    <>
      <SectionWrap>
        <SectionHead title="Upcoming Events" sub="Stay in the loop on meetings, recruitment events, and more." />
        <div style={{ maxWidth: 800, margin: "0 auto", display: "flex", flexDirection: "column", gap: 24 }}>
          {EVENTS.map((e, i) => (
            <div key={i} style={{
              display: "grid", gridTemplateColumns: "200px 1fr", borderRadius: 16, overflow: "hidden",
              background: C.white, border: `1px solid ${C.lightGray}`, boxShadow: "0 2px 12px rgba(0,0,0,.05)",
            }} className="eventCard">
              {e.photo
                ? <img src={e.photo} alt={e.title} style={{ width: "100%", aspectRatio: "4/3", objectFit: "cover", objectPosition: e.photoPosition || "center", display: "block" }} />
                : <PhotoPlaceholder hue={e.photoHue} aspect="4/3" label={e.type} style={{ borderRadius: 0 }} />
              }
              <div style={{ padding: "24px 28px", display: "flex", flexDirection: "column", justifyContent: "center" }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8 }}>
                  <span style={{
                    background: typeColors[e.type] || C.red,
                    color: C.white,
                    padding: "3px 12px", borderRadius: 50, fontSize: 11, fontWeight: 700,
                    fontFamily: font.display, textTransform: "uppercase", letterSpacing: 0.5,
                  }}>{e.type}</span>
                </div>
                <h3 style={{ fontFamily: font.display, fontSize: 20, fontWeight: 700, margin: "0 0 6px", color: C.charcoal }}>{e.title}</h3>
                <p style={{ fontFamily: font.body, fontSize: 13, color: C.textLight, margin: "0 0 4px" }}>
                  📅 {e.date} · 🕐 {e.time} · 📍 {e.loc}
                </p>
                <p style={{ fontFamily: font.body, fontSize: 14, color: C.textMid, lineHeight: 1.55, margin: "8px 0 0" }}>{e.desc}</p>
              </div>
            </div>
          ))}
        </div>
      </SectionWrap>

      {/* Past Events Recap */}
      <SectionWrap bg={C.offWhite}>
        <SectionHead title="Past Events" sub="A look back at what we've been up to." />
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(260px, 1fr))", gap: 20, maxWidth: 900, margin: "0 auto" }}>
          {PAST_EVENTS.map((e, i) => (
            <div key={i} style={{ borderRadius: 14, overflow: "hidden", background: C.white, border: `1px solid ${C.lightGray}` }}>
              {e.photo
                ? <img src={e.photo} alt={e.title} style={{ width: "100%", aspectRatio: "16/10", objectFit: "cover", objectPosition: e.photoPosition || "center", display: "block" }} />
                : <PhotoPlaceholder hue={e.photoHue} aspect="16/10" label="Event photo" />
              }
              <div style={{ padding: "16px 20px" }}>
                <h4 style={{ fontFamily: font.display, fontSize: 16, fontWeight: 700, margin: "0 0 4px", color: C.charcoal }}>{e.title}</h4>
                <p style={{ fontFamily: font.body, fontSize: 13, color: C.textLight, margin: 0 }}>{e.date}</p>
              </div>
            </div>
          ))}
        </div>
      </SectionWrap>

      <CelsiusBanner variant="strip" />

      {/* CTA */}
      <SectionWrap bg="#891824" style={{ textAlign: "center" }}>
        <h3 style={{ fontFamily: font.display, fontSize: 28, fontWeight: 800, color: C.white, margin: "0 0 12px" }}>Don't just watch. Participate.</h3>
        <p style={{ fontFamily: font.body, fontSize: 16, color: "rgba(255,255,255,.6)", margin: "0 0 28px" }}>Sign up and we'll get you into your first meeting.</p>
        <Btn onClick={() => setPage("Join")} variant="gold" style={{ fontSize: 16, padding: "14px 38px" }}>Sign Up</Btn>
      </SectionWrap>
    </>
  );
}

/* ═══════════════════════════════════════════ */
/* ═══ JOIN / SIGNUP PAGE ════════════════════ */
/* ═══════════════════════════════════════════ */
function JoinPage() {
  return (
    <SectionWrap style={{ textAlign: "center", minHeight: "60vh", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <div style={{ maxWidth: 520 }}>
        <div style={{ fontSize: 48, marginBottom: 20 }}>🌱</div>
        <h2 style={{ fontFamily: font.display, fontSize: 32, fontWeight: 800, color: C.charcoal, margin: "0 0 14px" }}>Closed Until Spring</h2>
        <p style={{ fontFamily: font.body, fontSize: 17, color: C.textMid, lineHeight: 1.6, margin: 0 }}>
          Sign-ups for Toastmasters at Miami University are currently closed. We'll reopen registration in the spring semester &mdash; check back soon!
        </p>
      </div>
    </SectionWrap>
  );
}

/* ═══ FOOTER ═══ */
function Footer({ setPage }) {
  return (
    <footer style={{ background: "#2E2E2E", padding: "48px clamp(20px, 5vw, 72px) 28px" }}>
      <div style={{ display: "flex", justifyContent: "space-between", flexWrap: "wrap", gap: 36, maxWidth: 1060, margin: "0 auto" }}>
        <div style={{ maxWidth: 280 }}>
          <div style={{ fontFamily: font.display, fontWeight: 800, fontSize: 18, color: C.white, marginBottom: 10 }}>Toastmasters at Miami University</div>
          <p style={{ fontFamily: font.body, fontSize: 13, color: "rgba(255,255,255,.5)", lineHeight: 1.6, margin: "0 0 16px" }}>
            Miami University · Oxford, Ohio<br />A chapter of Toastmasters International
          </p>
          <CelsiusBanner variant="inline" />
        </div>

        <div>
          <div style={{ fontFamily: font.display, fontWeight: 700, fontSize: 12, color: "rgba(255,255,255,.4)", marginBottom: 14, textTransform: "uppercase", letterSpacing: 1.5 }}>Pages</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            {[...PAGES, "Sign Up"].map(p => (
              <span key={p} onClick={() => setPage(p === "Sign Up" ? "Join" : p)} style={{ fontFamily: font.body, fontSize: 14, color: "rgba(255,255,255,.6)", cursor: "pointer" }}>{p}</span>
            ))}
          </div>
        </div>

        <div>
          <div style={{ fontFamily: font.display, fontWeight: 700, fontSize: 12, color: "rgba(255,255,255,.4)", marginBottom: 14, textTransform: "uppercase", letterSpacing: 1.5 }}>Connect</div>
          <div style={{ display: "flex", flexDirection: "column", gap: 8, fontFamily: font.body, fontSize: 14, color: "rgba(255,255,255,.6)" }}>
            <a href="mailto:toastmasters@miamioh.edu" style={{ color: "inherit", textDecoration: "none" }} onMouseEnter={e => e.currentTarget.style.textDecoration = "underline"} onMouseLeave={e => e.currentTarget.style.textDecoration = "none"}>Email: toastmasters@miamioh.edu</a>
            <a href="https://www.linkedin.com/in/toastmastersmiamiu" target="_blank" rel="noopener noreferrer" style={{ color: "inherit", textDecoration: "none" }} onMouseEnter={e => e.currentTarget.style.textDecoration = "underline"} onMouseLeave={e => e.currentTarget.style.textDecoration = "none"}>LinkedIn: Toastmasters at Miami University</a>
            <a href="https://www.instagram.com/toastmastersmiamiu/" target="_blank" rel="noopener noreferrer" style={{ color: "inherit", textDecoration: "none" }} onMouseEnter={e => e.currentTarget.style.textDecoration = "underline"} onMouseLeave={e => e.currentTarget.style.textDecoration = "none"}>Instagram: @toastmastersmiamiu</a>
            <a href="https://groupme.com/join_group/109522885/B7FIMY2b" target="_blank" rel="noopener noreferrer" style={{ color: "inherit", textDecoration: "none" }} onMouseEnter={e => e.currentTarget.style.textDecoration = "underline"} onMouseLeave={e => e.currentTarget.style.textDecoration = "none"}>GroupMe: Join the group</a>
          </div>
        </div>

        <div style={{ width: "100%", textAlign: "center" }}>
          <Btn onClick={() => setPage("Join")} variant="gold" style={{ marginBottom: 20, padding: "12px 32px" }}>Want to join? Sign Up →</Btn>
        </div>
      </div>

      <div style={{ borderTop: "1px solid rgba(255,255,255,.08)", marginTop: 20, paddingTop: 18, textAlign: "center", fontFamily: font.body, fontSize: 12, color: "rgba(255,255,255,.3)" }}>
        © {new Date().getFullYear()} Toastmasters at Miami University
      </div>
    </footer>
  );
}

/* ═══ APP ═══ */
export default function App() {
  const [page, setPage] = useState("Home");

  useEffect(() => { window.scrollTo({ top: 0, behavior: "smooth" }); }, [page]);

  const pages = {
    Home: <HomePage setPage={setPage} />,
    Team: <TeamPage />,
    Events: <EventsPage setPage={setPage} />,
    Join: <JoinPage />,
  };

  return (
    <div style={{ fontFamily: font.body, color: C.text, background: C.white }}>
      <Nav page={page} setPage={setPage} />
      <main style={{ marginTop: 60 }}>{pages[page]}</main>
      <Footer setPage={setPage} />
      <style>{`
        *{box-sizing:border-box;margin:0}
        body{margin:0;-webkit-font-smoothing:antialiased}
        button:hover{opacity:.88}
        input:focus,textarea:focus,select:focus{border-color:${C.red}!important;box-shadow:0 0 0 3px rgba(195,20,45,.1)}
        @media(max-width:768px){
          .heroGrid,.aboutGrid,.joinGrid{grid-template-columns:1fr!important}
          .heroPhoto{order:-1}
          .joinSide{order:-1}
          .photoStrip{grid-template-columns:1fr!important}
          .eventCard{grid-template-columns:1fr!important}
        }
      `}</style>
    </div>
  );
}
